/** 亮度标定：一颗 V 等星在底图单位下的辐亮度对立体角的积分 = STAR_BG_KSR · 10^(−0.4V)（sr；hiptyc 层上 3389 颗孤立星的中位数） */
export const STAR_BG_KSR = 9.62069e-5
